-- Money Compass question bank v2, generated from prototype/index.html so the
-- real app asks exactly what the prototype does. Adds everything the
-- prototype's adaptive flow needs:
--
--   hint / unit / min_value / max_value / scale_labels  presentation
--   variants          per-profile overrides of text, hint, unit and options,
--                     e.g. {"STUDENT": {"text": "...", "options": {...}}}
--   clarifies         this question is a simpler re-ask of <clarifies>, only
--                     served when that one was answered "I don't know"
--   value_map         how a clarifier's option maps back onto the original
--                     question's answer, e.g. {"B": {"number": 2}}
--   ask_if            a follow-up's trigger, evaluated by AskIfCondition:
--                     {"selectedIn": {"question": q, "values": [...]}}
--                     {"unknownOrNumberBelow": {"question": q, "value": n}}
--                     {"unknownOrScaleAtMost": {"question": q, "value": n}}
--                     {"knowledgeGap": "<CATEGORY>"}
--   follow_up_reason  shown above a follow-up, saying why it was asked
--   advanced          skipped once the user says "I don't know" in that
--                     category without getting any of its knowledge right
--   sort_order        the order questions are served in
--   knowledge_topic   what to call the topic when the user misses it
--   wiki_title        a Wikipedia article to read up on it
--   active            false for questions from v1 that are no longer asked;
--                     kept (not deleted) because old answers reference them
--
-- Branching now lives in ask_if/clarifies, so question_rules is emptied.
-- A NULL rubric means "not scored" (age, income, dependents, clarifiers).

ALTER TABLE questions
    ADD COLUMN hint             TEXT,
    ADD COLUMN unit             VARCHAR(64),
    ADD COLUMN min_value        NUMERIC,
    ADD COLUMN max_value        NUMERIC,
    ADD COLUMN scale_labels     JSONB,
    ADD COLUMN variants         JSONB,
    ADD COLUMN clarifies        VARCHAR(64),
    ADD COLUMN value_map        JSONB,
    ADD COLUMN ask_if           JSONB,
    ADD COLUMN follow_up_reason TEXT,
    ADD COLUMN advanced         BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN sort_order       INT     NOT NULL DEFAULT 1000,
    ADD COLUMN knowledge_topic  TEXT,
    ADD COLUMN wiki_title       TEXT,
    ADD COLUMN active           BOOLEAN NOT NULL DEFAULT TRUE;

DELETE FROM question_rules;
UPDATE questions SET active = FALSE;

INSERT INTO questions (code, text, type, options, category, applicable_profiles, weight, rubric,
                       hint, unit, min_value, max_value, scale_labels, variants,
                       clarifies, value_map, ask_if, follow_up_reason,
                       advanced, sort_order, knowledge_topic, wiki_title) VALUES
('age', 'How old are you?', 'NUMBER', NULL, 'BUDGETING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 1, NULL, 'Not scored — it sets your retirement timeline and how much risk suits your stage of life.', 'years', 15, 100, NULL, '{"STUDENT":{"hint":"Not scored — it tells us how many years your money has to grow."},"RETIREE":{"hint":"Not scored — it shapes how long your savings need to last and how much risk suits you."}}'::jsonb, NULL, NULL, NULL, NULL, FALSE, 10, NULL, NULL),
('monthly_income', 'Roughly what is your monthly take-home income?', 'NUMBER', NULL, 'BUDGETING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 1, NULL, 'What reaches your account after tax and EPF: salary, pension plus regular withdrawals, or allowance and part-time pay. Not scored — it sizes your plan.', '₹ per month', NULL, NULL, NULL, '{"STUDENT":{"text":"How much money comes to you in a typical month?","unit":"₹ per month","hint":"Pocket money, allowance, stipend, scholarship, part-time or internship pay — whatever reaches you. Enter 0 if nothing comes regularly. Not scored — it sizes your plan."},"RETIREE":{"text":"Roughly how much comes in each month?","unit":"₹ per month","hint":"Pension, annuity, interest, rent and any regular withdrawals from your savings, after tax. Not scored — it sizes your plan."},"PROFESSIONAL":{"hint":"Your salary as it lands in your account — after tax, EPF and other deductions — plus any regular side or freelance income. Not scored — it sizes your plan."}}'::jsonb, NULL, NULL, NULL, NULL, FALSE, 20, NULL, NULL),
('monthly_income_range_student', 'No problem — roughly how much comes to you in a typical month?', 'SINGLE', '{"A":"Nothing regular","B":"Under ₹2,000","C":"₹2,000 – ₹5,000","D":"₹5,000 – ₹15,000","E":"More than ₹15,000"}'::jsonb, 'BUDGETING', ARRAY['STUDENT'], 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'monthly_income', '{"A":{"number":0},"B":{"number":1000},"C":{"number":3500},"D":{"number":10000},"E":{"number":20000}}'::jsonb, NULL, NULL, FALSE, 30, NULL, NULL),
('monthly_income_range', 'No problem — which range is your monthly take-home (salary, pension, or allowance) closest to?', 'SINGLE', '{"A":"Under ₹25,000","B":"₹25,000 – ₹50,000","C":"₹50,000 – ₹1,00,000","D":"₹1,00,000 – ₹2,00,000","E":"Above ₹2,00,000"}'::jsonb, 'BUDGETING', ARRAY['PROFESSIONAL','RETIREE'], 1, NULL, NULL, NULL, NULL, NULL, NULL, '{"RETIREE":{"text":"No problem — which range is your monthly income (pension, interest, rent and withdrawals together) closest to?"},"PROFESSIONAL":{"text":"No problem — which range is your monthly in-hand salary (plus any regular side income) closest to?"}}'::jsonb, 'monthly_income', '{"A":{"number":15000},"B":{"number":37500},"C":{"number":75000},"D":{"number":150000},"E":{"number":250000}}'::jsonb, NULL, NULL, FALSE, 40, NULL, NULL),
('budgeting_expense_tracking', 'How do you currently track your monthly expenses?', 'SINGLE', '{"A":"I don''t track them at all","B":"Rough mental estimate","C":"Spreadsheet or app, checked occasionally","D":"Detailed tracking, reviewed every month"}'::jsonb, 'BUDGETING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 1, '{"optionPoints":{"A":0,"B":3,"C":7,"D":10}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 50, NULL, 'Personal budget'),
('budgeting_needs_wants', 'Which of these is a “want” rather than a “need”?', 'SINGLE', '{"A":"Rent for a room near your college or work","B":"Groceries for cooking at home","C":"Upgrading to a new phone while yours still works fine","D":"A health insurance premium"}'::jsonb, 'BUDGETING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 1, '{"correct":"C","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, '{"RETIREE":{"options":{"A":"Your regular medicines","B":"Groceries for cooking at home","C":"Upgrading to a new phone while yours still works fine","D":"A health insurance premium"}}}'::jsonb, NULL, NULL, NULL, NULL, FALSE, 60, 'needs vs. wants', 'Need'),
('budgeting_savings_rate', 'Roughly what percentage of your take-home income do you save or invest in a typical month?', 'NUMBER', NULL, 'BUDGETING', ARRAY['STUDENT','PROFESSIONAL'], 1, '{"numberThresholds":[{"min":20,"points":10},{"min":10,"points":6},{"min":0,"points":2}]}'::jsonb, 'Count SIPs, RDs, and money you move to savings. Leave out EPF — it''s already taken out before your take-home.', '% of take-home', NULL, NULL, NULL, '{"STUDENT":{"text":"Roughly what share of the money you get each month do you save or invest?","unit":"% of what you get","hint":"Count anything you put aside — money left in your savings account counts, and so does an SIP."}}'::jsonb, NULL, NULL, NULL, NULL, FALSE, 70, NULL, 'Saving'),
('budgeting_savings_rate_simple', 'Let''s try it another way — at the end of a typical month, how much of your income is usually left over?', 'SINGLE', '{"A":"Nothing, or I overspend","B":"A little — under a tenth of it","C":"Somewhere between a tenth and a fifth","D":"More than a fifth"}'::jsonb, 'BUDGETING', ARRAY['STUDENT','PROFESSIONAL'], 1, NULL, NULL, NULL, NULL, NULL, NULL, '{"STUDENT":{"text":"Let''s try it another way — at the end of a typical month, how much of your money is usually left over?"}}'::jsonb, 'budgeting_savings_rate', '{"A":{"number":0},"B":{"number":5},"C":{"number":15},"D":{"number":25}}'::jsonb, NULL, NULL, FALSE, 80, NULL, 'Saving'),
('budgeting_fixed_expenses', 'Which of these are usually fixed, hard-to-change monthly expenses? Select all that apply.', 'MULTI', '{"A":"Hostel or PG rent","B":"Weekend outings","C":"Mobile and internet plan","D":"Food delivery"}'::jsonb, 'BUDGETING', ARRAY['STUDENT'], 1, '{"correctSet":["A","C"],"points":10}'::jsonb, 'Select every option that applies.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 90, 'fixed vs. flexible expenses', 'Fixed cost'),
('budgeting_recurring_bills', 'How do you handle recurring bills — rent, EMI, utilities — each month?', 'SINGLE', '{"A":"I sometimes pay late","B":"I pay manually, but on time","C":"Auto-debit is set up for most of them","D":"Auto-debit is set up, and I review it monthly"}'::jsonb, 'BUDGETING', ARRAY['PROFESSIONAL'], 1, '{"optionPoints":{"A":0,"B":5,"C":8,"D":10}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 100, NULL, 'Direct debit'),
('retiree_budget_fixed_income', 'In retirement, how do you manage monthly expenses against your pension or withdrawal income?', 'SINGLE', '{"A":"I don''t have a clear budget","B":"A rough idea, no formal budget","C":"I track it monthly against my income","D":"I track it monthly and re-check it against inflation each year"}'::jsonb, 'BUDGETING', ARRAY['RETIREE'], 1, '{"optionPoints":{"A":0,"B":3,"C":7,"D":10}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 110, NULL, 'Personal budget'),
('saving_emergency_fund_months', 'How many months of essential expenses could you cover from money you can withdraw within a few days?', 'NUMBER', NULL, 'SAVING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 2, '{"numberThresholds":[{"min":6,"points":10},{"min":3,"points":6},{"min":1,"points":3},{"min":0,"points":0}]}'::jsonb, 'Count savings accounts, liquid funds and FDs you can break. Leave out stocks, PPF, EPF and gold.', 'months', NULL, NULL, NULL, '{"STUDENT":{"text":"If you suddenly needed money — a broken phone, a doctor''s visit, a trip home — how many months of your usual spending could you cover from your own savings, without asking anyone?","hint":"Count savings you can get to within a few days. Money your family would step in with doesn''t count here."},"RETIREE":{"hint":"Count savings accounts, liquid funds and FDs you can break early. Leave out money locked in SCSS, annuities, equity and gold."}}'::jsonb, NULL, NULL, NULL, NULL, FALSE, 120, NULL, 'Emergency fund'),
('saving_emergency_fund_simple', 'Put simply: if your income stopped today, how long could you keep paying rent, food and bills from money you can get to quickly?', 'SINGLE', '{"A":"Less than a month","B":"1 to 3 months","C":"3 to 6 months","D":"More than 6 months"}'::jsonb, 'SAVING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 2, NULL, NULL, NULL, NULL, NULL, NULL, '{"STUDENT":{"text":"Put simply: if your pocket money or stipend stopped, how long could your own savings cover your usual spending — phone, travel, food outside home?"},"RETIREE":{"text":"Put simply: if your pension or other income was held up, how long could you keep paying for food, medicines and bills from money you can get to quickly?"},"PROFESSIONAL":{"text":"Put simply: if you lost your job today, how long could you keep paying rent, EMIs, food and bills from money you can get to quickly?"}}'::jsonb, 'saving_emergency_fund_months', '{"A":{"number":0},"B":{"number":2},"C":{"number":4},"D":{"number":6}}'::jsonb, NULL, NULL, FALSE, 130, NULL, 'Emergency fund'),
('saving_emergency_fund_where', 'Where is the most sensible place to keep an emergency fund?', 'SINGLE', '{"A":"In stocks, so it grows faster","B":"A savings account or liquid fund you can withdraw from any day","C":"Gold jewellery at home","D":"A 5-year locked tax-saver FD"}'::jsonb, 'SAVING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 1, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"unknownOrNumberBelow":{"question":"saving_emergency_fund_months","value":3}}'::jsonb, 'Follow-up — your emergency cushion looks thin, so a quick check on where one should live.', FALSE, 140, 'where to keep an emergency fund', 'Money market fund'),
