('risk_drop_rupees', 'Imagine you invested ₹1,00,000 and a month later it''s worth ₹80,000. What would you most likely do?', 'SINGLE', '{"A":"Sell everything before it falls further","B":"Sell some of it","C":"Leave it alone and wait","D":"Invest a bit more while prices are low"}'::jsonb, 'RISK', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 2, NULL, NULL, NULL, NULL, NULL, NULL, '{"STUDENT":{"text":"Imagine you invested ₹10,000 and a month later it''s worth ₹8,000. What would you most likely do?"}}'::jsonb, 'risk_market_drop_reaction', '{"A":{"scale":1},"B":{"scale":2},"C":{"scale":4},"D":{"scale":5}}'::jsonb, NULL, NULL, FALSE, 340, NULL, 'Loss aversion'),
