('retiree_inflation_awareness', 'Over a 20-year retirement, which of these typically poses the bigger risk to your purchasing power?', 'SINGLE', '{"A":"Day-to-day market volatility","B":"Inflation quietly eroding fixed income","C":"Bank service charges","D":"Currency exchange rates"}'::jsonb, 'RISK', ARRAY['RETIREE'], 1, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 380, 'inflation risk in retirement', 'Inflation'),
('compounding_rule_of_72', 'Using the Rule of 72, roughly how many years does it take to double your money at 8% annual return?', 'SINGLE', '{"A":"4 years","B":"9 years","C":"14 years","D":"20 years"}'::jsonb, 'COMPOUNDING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 2, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 390, 'the Rule of 72', 'Rule of 72'),
('compounding_early_start', 'Two people invest the same amount monthly. Person A starts at 25, Person B at 35; both stop at 45 and let it grow, untouched, at the same return. Who generally ends up with more?', 'SINGLE', '{"A":"Person A","B":"Person B","C":"They always end up equal","D":"Impossible to know"}'::jsonb, 'COMPOUNDING', ARRAY['STUDENT','PROFESSIONAL'], 2, '{"correct":"A","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 400, 'the cost of starting late', 'Compound interest'),
('compounding_pay_rise', 'You get a 15% raise. What usually does the most for your long-term wealth?', 'SINGLE', '{"A":"Upgrade your lifestyle by the full amount — you''ve earned it","B":"Raise your SIP by part of the raise before your spending catches up","C":"Leave the extra sitting in your savings account","D":"Take a bigger loan now that you can afford a larger EMI"}'::jsonb, 'COMPOUNDING', ARRAY['PROFESSIONAL'], 1, '{"optionPoints":{"A":0,"B":10,"C":4,"D":0}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 410, NULL, 'Lifestyle creep'),
('compounding_basics_probe', 'You deposit ₹10,000 at 10% interest a year, compounded yearly, and don''t touch it. Roughly how much is there after 2 years?', 'SINGLE', '{"A":"₹11,000","B":"₹12,000","C":"₹12,100","D":"₹20,000"}'::jsonb, 'COMPOUNDING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 1, '{"correct":"C","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"knowledgeGap":"COMPOUNDING"}'::jsonb, 'Follow-up — checking the basics of compounding before we call it a gap.', FALSE, 420, 'how compound interest adds up', 'Compound interest'),
('investing_index_fund_def', 'What does an index fund do?', 'SINGLE', '{"A":"Actively picks stocks to try to beat the market","B":"Tracks a market index, like the Nifty 50, passively","C":"Guarantees a fixed return","D":"Only invests in gold"}'::jsonb, 'INVESTING', ARRAY['STUDENT','PROFESSIONAL'], 2, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 430, 'what index funds do', 'Index fund'),
('investing_first_step', 'As a student with limited money to invest, what''s a reasonable way to start?', 'SINGLE', '{"A":"Wait until I have a large lump sum","B":"Try to time the market for the perfect entry point","C":"Start a small SIP in an index fund","D":"Put everything into one hot stock tip"}'::jsonb, 'INVESTING', ARRAY['STUDENT'], 1, '{"optionPoints":{"A":2,"B":0,"C":10,"D":0}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 440, NULL, 'Dollar-cost averaging'),
('investing_scam_check', 'A senior adds you to a Telegram group promising "guaranteed 10% a month" from trading or crypto. What''s the best way to read it?', 'SINGLE', '{"A":"Join fast — early members earn the most","B":"Try a small amount first to test it","C":"Treat it as a likely scam: no genuine investment can guarantee returns like that","D":"It''s fine if lots of people vouch for it"}'::jsonb, 'INVESTING', ARRAY['STUDENT'], 1, '{"correct":"C","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 450, 'spotting "guaranteed return" scams', 'Ponzi scheme'),
('investing_elss_lockin', 'What is the lock-in period for ELSS (tax-saving) mutual funds in India?', 'SINGLE', '{"A":"No lock-in","B":"1 year","C":"3 years","D":"5 years"}'::jsonb, 'INVESTING', ARRAY['PROFESSIONAL'], 1, '{"correct":"C","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 460, 'the ELSS lock-in', 'Equity Linked Savings Scheme'),
('investing_80c_options', 'Under the old tax regime, which of these can you claim as deductions under Section 80C? Select all that apply.', 'MULTI', '{"A":"PPF","B":"ELSS mutual funds","C":"Regular savings account","D":"5-year tax-saver FD"}'::jsonb, 'INVESTING', ARRAY['PROFESSIONAL'], 1, '{"correctSet":["A","B","D"],"points":10}'::jsonb, 'Select every option that applies. The new regime (the default since 2023) doesn''t allow 80C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 470, 'Section 80C options', 'Income tax in India'),
('investing_tax_regime', 'Since FY 2025-26, under the new tax regime, a salaried person earning up to about how much a year pays no income tax at all?', 'SINGLE', '{"A":"₹5 lakh","B":"₹7.75 lakh","C":"₹12.75 lakh","D":"₹20 lakh"}'::jsonb, 'INVESTING', ARRAY['PROFESSIONAL'], 1, '{"correct":"C","points":10}'::jsonb, 'The new regime is the default; you can still choose the old one if your deductions (80C, HRA, home loan) are large.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 480, 'the new tax regime''s ₹12.75 lakh zero-tax limit', 'Income tax in India'),
('retiree_scss_awareness', 'What is the Senior Citizens'' Savings Scheme (SCSS)?', 'SINGLE', '{"A":"A government-backed fixed-income scheme, mainly for people aged 60 and over","B":"A private equity mutual fund","C":"A type of health insurance policy","D":"A tax filing category"}'::jsonb, 'INVESTING', ARRAY['RETIREE'], 1, '{"correct":"A","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 490, 'the Senior Citizens'' Savings Scheme', 'India Post'),
('retiree_swp_def', 'What does an SWP (Systematic Withdrawal Plan) let you do?', 'SINGLE', '{"A":"Invest a fixed amount every month","B":"Withdraw a fixed amount from your investments at regular intervals","C":"Automatically switch between mutual funds","D":"Borrow against your mutual fund units"}'::jsonb, 'INVESTING', ARRAY['RETIREE'], 1, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 500, 'systematic withdrawal plans (SWP)', 'Retirement spend-down'),
('investing_basics_probe', 'Why is spreading your money across many companies usually safer than putting it all into one?', 'SINGLE', '{"A":"It guarantees a higher return","B":"One company doing badly hurts you much less","C":"It avoids all taxes","D":"It isn''t — one good company is always safer"}'::jsonb, 'INVESTING', ARRAY['STUDENT','PROFESSIONAL','RETIREE'], 1, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"knowledgeGap":"INVESTING"}'::jsonb, 'Follow-up — checking the basics of investing before we call it a gap.', FALSE, 510, 'diversification', 'Diversification (finance)'),
('retirement_ppf_lockin', 'What is the standard maturity period of a PPF account in India?', 'SINGLE', '{"A":"5 years","B":"10 years","C":"15 years","D":"21 years"}'::jsonb, 'RETIREMENT', ARRAY['PROFESSIONAL','RETIREE'], 1, '{"correct":"C","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 520, 'PPF maturity', 'Public Provident Fund (India)'),
('retirement_readiness', 'How confident are you that your current savings and investments are on track for retirement?', 'SCALE', NULL, 'RETIREMENT', ARRAY['PROFESSIONAL','RETIREE'], 1, '{"scale":{"1":0,"2":3,"3":5,"4":8,"5":10}}'::jsonb, NULL, NULL, NULL, NULL, '["Not confident","Very confident"]'::jsonb, '{"RETIREE":{"text":"How confident are you that your savings and investments will last through your retirement?"}}'::jsonb, NULL, NULL, NULL, NULL, FALSE, 530, NULL, 'Retirement planning'),
('retirement_nps_tax', 'Under the old tax regime, which section gives an extra deduction of up to ₹50,000 for your own NPS contributions, beyond the ₹1.5 lakh 80C limit?', 'SINGLE', '{"A":"80D","B":"80CCD(1B)","C":"80G","D":"80TTA"}'::jsonb, 'RETIREMENT', ARRAY['PROFESSIONAL'], 1, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 540, 'the extra NPS deduction, 80CCD(1B)', 'National Pension System'),
('retirement_epf_job_change', 'When you change jobs, what''s usually best to do with your EPF balance?', 'SINGLE', '{"A":"Withdraw it — it''s a nice bonus","B":"Transfer it to your new employer''s account using your UAN","C":"Leave it in the old account and forget about it","D":"Withdraw half, keep half"}'::jsonb, 'RETIREMENT', ARRAY['PROFESSIONAL'], 1, '{"optionPoints":{"A":0,"B":10,"C":4,"D":2}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 550, NULL, 'Employees'' Provident Fund Organisation'),
('retirement_corpus_estimate', 'Roughly how many times your current annual expenses do you think you''ll need saved by retirement?', 'NUMBER', NULL, 'RETIREMENT', ARRAY['PROFESSIONAL'], 1, '{"numberThresholds":[{"min":20,"points":10},{"min":15,"points":6},{"min":10,"points":3},{"min":0,"points":0}]}'::jsonb, NULL, '× annual expenses', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 560, NULL, 'Trinity study'),
('retiree_runway_years', 'At your current rate of spending from savings, roughly how many years do you estimate your retirement corpus would comfortably last?', 'NUMBER', NULL, 'RETIREMENT', ARRAY['RETIREE'], 1, '{"numberThresholds":[{"min":25,"points":10},{"min":15,"points":6},{"min":8,"points":3},{"min":0,"points":0}]}'::jsonb, NULL, 'years', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 570, NULL, 'Retirement spend-down'),
('retiree_healthcare_fund', 'Do you have a dedicated health insurance or medical emergency fund, separate from your main retirement corpus?', 'SINGLE', '{"A":"No","B":"I''ve been meaning to","C":"Yes, a small one","D":"Yes, sized for a major medical event"}'::jsonb, 'RETIREMENT', ARRAY['RETIREE'], 1, '{"optionPoints":{"A":0,"B":3,"C":7,"D":10}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 580, NULL, 'Health insurance in India'),
('retiree_withdrawal_rate', 'Roughly what share of your savings can you withdraw each year, so they''re likely to last 25–30 years?', 'SINGLE', '{"A":"About 1%","B":"About 3–4%","C":"About 8–10%","D":"About 15%"}'::jsonb, 'RETIREMENT', ARRAY['RETIREE'], 1, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 590, 'a safe yearly withdrawal rate', 'Trinity study'),
('retiree_nomination_will', 'Have you added nominees to your bank accounts, FDs and investments, and made a will?', 'SINGLE', '{"A":"Neither","B":"Nominees on some accounts, no will","C":"Nominees on all accounts, but no will yet","D":"Nominees everywhere, and a will"}'::jsonb, 'RETIREMENT', ARRAY['RETIREE'], 1, '{"optionPoints":{"A":0,"B":3,"C":6,"D":10}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, 600, NULL, 'Will and testament'),
('retiree_form_15h', 'If your total income is below the taxable limit, which form stops your bank deducting tax (TDS) from your FD interest?', 'SINGLE', '{"A":"Form 15G","B":"Form 15H","C":"Form 16","D":"Form 26AS"}'::jsonb, 'RETIREMENT', ARRAY['RETIREE'], 1, '{"correct":"B","points":10}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 610, 'Form 15H for tax on FD interest', 'Tax deduction at source')
